/// What an order came to. ok() unless refused; outcome is the venue's word; a refusal's reason is the venue's own
/// sentence, kind the word a program branches on, remedy what to change and docs the page (each null when absent).
/// raw is the whole answer.
struct Answer {
    std::string outcome;
    Json reason, kind, remedy, docs, ticket, order;
    Json raw;

    explicit Answer(const Json &answer) : raw(answer) {
        auto get = [&](const char *k) -> Json {
            if (!answer[k].is_null()) return answer[k];
            return answer["last_answer"][k];
        };
        Json o = get("outcome");
        outcome = o.is_string() && !o.str().empty() ? o.str() : "sent";
        reason = get("reason");
        kind = get("kind");
        remedy = get("remedy");
        docs = get("docs");
        ticket = get("ticket");
        order = get("order");
    }

    bool ok() const { return outcome != "refused"; }
};

/// A refusal raised, when the workbench was opened with raise_refusals: the answer is on it.
struct Refused : Error {
    Answer answer;
    explicit Refused(const Answer &a) : Error(a.reason.is_string() ? a.reason.str() : a.outcome), answer(a) {}
};

